    public function search(string $query = '', string $category = 'Alle', string $article = ''): array
    {
        return collect($this->articles())
            ->filter(fn ($item) => $article === '' || $item['id'] === $article)
            ->filter(fn ($item) => $category === 'Alle' || $item['category'] === $category)
            ->map(function ($item) use ($query) {
                $item['score'] = trim($query) === '' ? 1 : $this->search->score($query, [
                    'title' => $item['title'],
                    'terms' => [$item['purpose'], $item['path'], implode(' ', $item['steps']), $item['after'], $item['important']],
                    'aliases' => $item['keywords'],
                ]);
                return $item;
            })->filter(fn ($item) => $item['score'] !== null)->sortByDesc('score')->values()->all();
    }
